// Writes docs/openapi.json and docs/api.md from the route catalogue.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { buildOpenApi } from '../src/lib/openapi.js';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../../docs');
const doc = buildOpenApi();
fs.mkdirSync(root, { recursive: true });
fs.writeFileSync(path.join(root, 'openapi.json'), JSON.stringify(doc, null, 2));

const lines = [
  '# Systory HRMS — API (Stage 1)',
  '',
  'Generated by `npm -w backend run docs:api`. Interactive docs: start the backend and open http://localhost:4000/api/docs.',
  '',
  'All endpoints except those marked public need `Authorization: Bearer <accessToken>`. Lists accept `page`, `pageSize` (≤100), `search`, `sort=field:asc|desc` and return `{ data, meta: { page, pageSize, total } }`. Errors return `{ error: { code, message, details? } }`; `message` is an i18n key.',
  '',
];
const byTag = new Map<string, string[]>();
for (const [p, ops] of Object.entries(doc.paths ?? {})) {
  for (const [method, op] of Object.entries(ops as Record<string, any>)) {
    const tag = op.tags?.[0] ?? 'Other';
    const perm = /`([^`]+)`/.exec(op.description ?? '')?.[1] ?? (op.security?.length === 0 ? 'public' : 'signed in');
    if (!byTag.has(tag)) byTag.set(tag, []);
    byTag.get(tag)!.push(`| ${method.toUpperCase()} | \`${p}\` | ${op.summary} | ${perm} |`);
  }
}
for (const [tag, rows] of byTag) {
  lines.push(`## ${tag}`, '', '| Method | Path | Purpose | Permission |', '|---|---|---|---|', ...rows, '');
}
fs.writeFileSync(path.join(root, 'api.md'), lines.join('\n'));
console.log(`Wrote ${path.join(root, 'openapi.json')} and api.md`);
